SELECT
${page.fields}
FROM ( SELECT tag,'7' as active_sys,stat_time, sum(asum) asum, sum(bsum) bsum, SUM(absum) absum,service FROM (select tag, asum, bsum, absum, stat_time,service from (select tag, stat_time,service, asum, bsum, decode(asum, 0, bsum, asum) absum from (SELECT SUM(CASE WHEN PZ.ACTIVE_SYS = 4 THEN SUM ELSE 0 END) ASUM, SUM(CASE WHEN PZ.ACTIVE_SYS = 2 THEN SUM ELSE 0 END) BSUM,
PZ.stat_time, pz.config_id, pz.tag,pz.service FROM df_cfg_tag_stat_log_daily PZ
and service=#{searchService}
and tag=#{searchTag}
AND stat_time >= to_date(#{searchStatStartTime},'yyyy-MM-dd HH24:mi:ss')
AND stat_time < to_date(#{searchStatEndTime},'yyyy-MM-dd HH24:mi:ss')
GROUP BY pz.config_id, pz.tag, PZ.stat_time,pz.service)) a) group by tag, stat_time,service
)
ORDER BY ${page.orderBy}

